<script setup lang="ts">
import { computed,ref } from 'vue';
import { state,ui } from '../state';
import { coverageRows,coverageLabels,type CoverageStatus } from '../domain/coverage-tracker';
import { planningLocations } from '../domain/planning-locations';
import { downloadFile } from '../services/data-files';
const query=ref(''),status=ref(''),theme=ref(''),stage=ref(''),stream=ref('');
const statuses=['unaddressed','partial','planned'] as CoverageStatus[];
const rows=computed(()=>coverageRows(state.value!.requirements,state.value!.progress.activities??[],state.value!.studio.schedule??[],{},[]));
const themes=computed(()=>[...new Set(state.value!.requirements.flatMap(r=>(r.theme_tags as string[]|undefined)??r.tags))].sort());
const filtered=computed(()=>rows.value.filter(o=>{
 const r=o.requirement;
 return (!status.value||o.status===status.value)&&(!stage.value||String(r.stage)===stage.value)&&(!stream.value||r.stream===stream.value)&&(!theme.value||((r.theme_tags as string[]|undefined)??r.tags).includes(theme.value))&&(!query.value||`${r.text} ${r.id} ${r.tags.join(' ')} ${r.stream}`.toLowerCase().includes(query.value.toLowerCase()));
}));
function addressedCsv(){const lines=[['Requirement ID','Requirement','Stage','Stream','Preferred location','Alternative locations','Linked activities','Planned opportunities','Required opportunities'],...rows.value.map(o=>[o.requirement.id,o.requirement.text,o.requirement.stage,o.requirement.stream,planningLocations(o.requirement).preferred??'Flexible / anywhere',(planningLocations(o.requirement).alternatives??[]).join('; '),o.activities.length,o.planned,o.needed])];return lines.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');}
</script>
<template><section class="coverage-tracker"><h2>Addressed requirements</h2><p>Track linked activities and scheduled opportunities. This describes planning coverage.</p>
 <div class="toolbar filter-panel"><label>Search tracker<input v-model="query" type="search" placeholder="Requirement, text or tag"></label><label>Coverage status<select v-model="status" aria-label="Coverage status"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{coverageLabels[s]}}</option></select></label><label>Theme<select v-model="theme" aria-label="Tracker theme"><option value="">All themes</option><option v-for="t in themes" :key="t">{{t}}</option></select></label><label>Stage<select v-model="stage" aria-label="Tracker stage"><option value="">All stages</option><option v-for="s in [1,2,3]" :key="s">{{s}}</option></select></label><label>Stream<select v-model="stream" aria-label="Tracker stream"><option value="">All streams</option><option>Camping</option><option>Bushwalking</option><option>Bushcraft</option></select></label><button @click="downloadFile('oas-requirement-coverage.csv',addressedCsv())">Export tracker CSV</button></div>
 <p>{{filtered.length}} of {{rows.length}} requirements</p><div class="table-scroll" tabindex="0" aria-label="Requirement coverage table"><table class="coverage-table"><thead><tr><th>Requirement</th><th>Stage / Stream</th><th>Activity Studio coverage</th><th>Planned / needed</th><th>Locations</th></tr></thead><tbody><tr v-for="o in filtered" :key="o.requirement.id"><td><button class="text-link" @click="ui.requirementId=o.requirement.id">{{o.requirement.text}}</button></td><td>Stage {{o.requirement.stage}}<small>{{o.requirement.stream}}</small></td><td>{{o.activities.length}} linked<small v-if="o.activities.length">{{o.activities.map(a=>a.title||a.id).slice(0,2).join('; ')}}</small></td><td>{{o.planned}} / {{o.needed}}<small>{{o.weeks.length?'Weeks '+o.weeks.join(', '):'Not scheduled'}}</small></td><td>{{planningLocations(o.requirement).preferred||'Flexible / anywhere'}}<small v-if="planningLocations(o.requirement).alternatives?.length">Also: {{planningLocations(o.requirement).alternatives!.join(', ')}}</small></td></tr><tr v-if="!filtered.length"><td colspan="5">No requirements match these filters.</td></tr></tbody></table></div></section></template>
